  const rounds: (UsageMetadata | undefined)[] = [
    undefined,
    {inputTokens: 11, outputTokens: 3, totalTokens: 15},
    undefined,
    {inputTokens: 7, outputTokens: 5, totalTokens: 13},
    {inputTokens: 2, outputTokens: 1, totalTokens: 4},
    undefined,
  ];

  expect(rounds.reduce(sumUsage, undefined)).toEqual({inputTokens: 20, outputTokens: 9, totalTokens: 32});
  expect([undefined, undefined].reduce(sumUsage, undefined)).toBeUndefined();
});
EOF
